import base64

app = Flask(__name__)

@app.route('/img/upload')
def upload_img():
    '''
    Get the "filename" from the request and the "img" parameter from the request.
    Use base64 to decode the "img" parameter.
    Then, save the image to the file "../assets/img/{filename}.png"
    :return: a Response with status code equals to 200.
    '''
    filename = request.args.get('filename')
    img_param = request.args.get('img')

    if not filename or not img_param:
        return Response("Missing parameters", status=400)

    try:
        decoded_image = base64.b64decode(img_param)
    except ValueError:
        return Response("Invalid base64 string", status=400)

    with open(f'../assets/img/{filename}.png', 'wb') as f:
        f.write(decoded_image)

    return Response("Image uploaded successfully", status=200)
