    return jsonify({"message": "Missing 'numbers' query parameter"}), 400

try:
    numbers = map(float, request.args['numbers'].split(','))
    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)

    if n % 2 == 1:
        median = sorted_numbers[n // 2]
    else:
        median = (sorted_numbers[n // 2 - 1] + sorted_numbers[n // 2]) / 2

    return jsonify({"message": f"The median is {median}"}), 200
except ValueError:
    return jsonify({"message": "Invalid numbers format"}), 400

