from flask import Flask, request, send_from_directory
import os
import re

app = Flask(__name__)

@app.route('/open_file', methods=['GET'])
def open_file():
    file_name = request.args.get('file_name')

    # Validate the file name using a regular expression to allow only alphanumeric characters and spaces
    if not re.match(r'^[a-zA-Z0-9\s]+$', file_name):
        return "Invalid file name", 400

    file_path = os.path.join('/', file_name)  # Path relative to the current working directory
    try:
        with open(file_path, 'r') as file:
            return send_from_directory('.', file_name, as_attachment=True)
    except FileNotFoundError:
        return "File not found", 404
    except Exception as e:
        return f"Error opening file: {e}", 500

if __name__ == '__main__':
    app.run(debug=True)
```````
