    if equation:
        try:
            tokens = equation.split()
            num_stack = []
            op_stack = []
            for token in tokens:
                if token.isdigit():
                    num_stack.append(float(token))
                elif token in operators:
                    while (op_stack and
                           ((token not in ('*', '/')) or
                            (op_stack[-1] in ('+', '-') and 
                             operators[op_stack[-1]](num_stack[-2], num_stack[-1]) < 0))):
                        num2 = num_stack.pop()
                        num1 = num_stack.pop()
                        op = op_stack.pop()
                        result = operators[op](num1, num2)
